    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]

    # Track all non-background cells
    cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                cells.append((r, c, grid[r][c]))

    # For each cell, compute its new position
    result = [[bg] * cols for _ in range(rows)]

    for r, c, val in cells:
        if c < cols - 1:
            result[r][c + 1] = val
        else:
            result[r][c] = val

    return result
